// EComm — standalone scene 6 (Scene6Build). Transparent background, no scene-level
// fade in/out. Content animates in via its own springs; <Background/> + SceneWrap removed.
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  sceneExit,
  ambientDrift,
} from "../motion";

const COLORS = {
  bg: "#161718",
  card: "#1d1e1f",
  border: "#3d3f43",
  text: "#f4f4f5",
  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "monospace";


const Scene6Build: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const cardIn = springIn(frame, vfps, 4, "LIQUID");

  // Weekly refresh ring
  const refreshAngle = interpolate(frame, [10, 60], [0, 360], {
    extrapolateRight: "clamp",
  });

  // Locations grid - 32 mini pins (8 cols × 4 rows)
  const pins = React.useMemo(() => {
    const arr: { row: number; col: number; isAlert: boolean }[] = [];
    const cols = 8;
    const rows = 4;
    const alertSet = new Set([5, 14, 25]);
    for (let i = 0; i < cols * rows; i++) {
      arr.push({
        row: Math.floor(i / cols),
        col: i % cols,
        isAlert: alertSet.has(i),
      });
    }
    return arr;
  }, []);

  // Alerts surface around frame 70-110
  const alertSurface = (i: number) => {
    return interpolate(
      frame,
      [75 + i * 8, 95 + i * 8],
      [0, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
    );
  };

  const driftY = ambientDrift(frame, 2, 120, "build");

  const alertIndices = [5, 14, 25];

  return (
    <AbsoluteFill>
      <AbsoluteFill
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          padding: base * 0.06,
          transform: `translateY(${driftY}px)`,
        }}
      >
        <div
          style={{
            position: "relative",
            width: width * 0.42,
            background: COLORS.card,
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.02,
            padding: base * 0.035,
            opacity: cardIn,
            transform: `translateX(${interpolate(cardIn, [0, 1], [-width * 0.6, 0])}px) translateY(${interpolate(cardIn, [0, 1], [30, 0])}px) scale(${interpolate(cardIn, [0, 1], [0.94, 1])})`,
            boxShadow: "0 24px 64px rgba(0,0,0,0.5)",
          }}
        >
          {/* Header */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: base * 0.016,
              marginBottom: base * 0.025,
              paddingBottom: base * 0.018,
              borderBottom: `1px solid ${COLORS.border}`,
            }}
          >
            <svg
              width={base * 0.024}
              height={base * 0.024}
              viewBox="0 0 24 24"
              fill="none"
              style={{
                transform: `rotate(${refreshAngle}deg)`,
              }}
            >
              <path
                d="M21 12 A9 9 0 1 1 12 3"
                stroke={COLORS.orange}
                strokeWidth={2.5}
                strokeLinecap="round"
                fill="none"
              />
              <path
                d="M21 3 L21 9 L15 9"
                stroke={COLORS.orange}
                strokeWidth={2.5}
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
              />
            </svg>
            <div
              style={{
                fontFamily: FONT_MARKETING,
                fontWeight: 600,
                fontSize: base * 0.02,
                color: COLORS.text,
                letterSpacing: "-0.01em",
              }}
            >
              32 Locations · Weekly
            </div>
            <div style={{ flex: 1 }} />
            {/* Live indicator */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: base * 0.008,
              }}
            >
              <div
                style={{
                  width: base * 0.01,
                  height: base * 0.01,
                  borderRadius: "50%",
                  background: COLORS.orange,
                  opacity:
                    0.6 + 0.4 * Math.sin(frame / 6),
                }}
              />
              <div
                style={{
                  fontFamily: FONT_MONO,
                  fontSize: base * 0.012,
                  color: COLORS.textMuted,
                  letterSpacing: "0.1em",
                  textTransform: "uppercase",
                }}
              >
                Live
              </div>
            </div>
          </div>

          {/* Pin grid */}
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(8, 1fr)",
              gap: base * 0.01,
              marginBottom: base * 0.025,
            }}
          >
            {pins.map((pin, i) => {
              const pinIn = staggeredSpring(
                frame,
                vfps,
                i,
                10,
                0.6,
                "ELASTIC"
              );
              const alertProg = pin.isAlert ? alertSurface(alertIndices.indexOf(i)) : 0;
              const grow = pin.isAlert
                ? interpolate(alertProg, [0, 1], [1, 1.5])
                : 1;

              const baseOpacity = pin.isAlert ? 1 : 0.6;

              return (
                <div
                  key={i}
                  style={{
                    aspectRatio: "1",
                    background: pin.isAlert
                      ? interpolate(alertProg, [0, 1], [0, 1]) > 0.5
                        ? COLORS.orangeDeep
                        : "rgba(255,255,255,0.08)"
                      : "rgba(255,255,255,0.06)",
                    border: pin.isAlert
                      ? `1.5px solid ${COLORS.orange}`
                      : `1px solid ${COLORS.border}`,
                    borderRadius: base * 0.004,
                    opacity: pinIn * baseOpacity,
                    transform: `scale(${pinIn * grow})`,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    boxShadow: pin.isAlert && alertProg > 0.5
                      ? `0 0 ${base * 0.015}px rgba(248,102,6,${0.4 * alertProg})`
                      : "none",
                  }}
                >
                  {pin.isAlert && alertProg > 0.3 && (
                    <div
                      style={{
                        width: "30%",
                        height: "30%",
                        borderRadius: "50%",
                        background: COLORS.text,
                        opacity: alertProg,
                      }}
                    />
                  )}
                </div>
              );
            })}
          </div>

          {/* Bottom status row */}
          <div
            style={{
              display: "flex",
              gap: base * 0.014,
              alignItems: "center",
            }}
          >
            {/* Needs attention badge */}
            <div
              style={{
                background: COLORS.card,
                border: `1.5px solid ${COLORS.orange}`,
                borderRadius: base * 0.006,
                padding: `${base * 0.008}px ${base * 0.014}px`,
                display: "flex",
                alignItems: "center",
                gap: base * 0.008,
                opacity: interpolate(
                  frame,
                  [80, 105],
                  [0, 1],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                ),
                transform: `translateY(${interpolate(
                  frame,
                  [80, 105],
                  [10, 0],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                )}px)`,
              }}
            >
              <div
                style={{
                  width: base * 0.012,
                  height: base * 0.012,
                  borderRadius: "50%",
                  background: COLORS.orange,
                }}
              />
              <div
                style={{
                  fontFamily: FONT_PRIMARY,
                  fontSize: base * 0.014,
                  color: COLORS.orange,
                  fontWeight: 600,
                  letterSpacing: "-0.005em",
                }}
              >
                3 need attention
              </div>
            </div>

            {/* OK badge */}
            <div
              style={{
                background: COLORS.card,
                border: `1px solid ${COLORS.border}`,
                borderRadius: base * 0.006,
                padding: `${base * 0.008}px ${base * 0.014}px`,
                display: "flex",
                alignItems: "center",
                gap: base * 0.008,
                opacity: interpolate(
                  frame,
                  [95, 120],
                  [0, 1],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                ),
                transform: `translateY(${interpolate(
                  frame,
                  [95, 120],
                  [10, 0],
                  {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  }
                )}px)`,
              }}
            >
              <svg
                width={base * 0.012}
                height={base * 0.012}
                viewBox="0 0 24 24"
                fill="none"
              >
                <path
                  d="M5 12.5 L10 17.5 L19 7"
                  stroke={COLORS.textMuted}
                  strokeWidth={3}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  fill="none"
                />
              </svg>
              <div
                style={{
                  fontFamily: FONT_PRIMARY,
                  fontSize: base * 0.014,
                  color: COLORS.textMuted,
                  fontWeight: 500,
                  letterSpacing: "-0.005em",
                }}
              >
                29 stable
              </div>
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// =====================================================
// MAIN COMPOSITION
// =====================================================

export const fps = 25;
export const durationInFrames = 338;
export default Scene6Build;
